css:
.activist-sim-container {
    padding: 20px;
    background: linear-gradient(160deg, #0f1626 0%, #1a2236 55%, #232c44 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e8edf6;
}

.activist-sim-header {
    background: linear-gradient(135deg, #7a0d1c 0%, #b1182b 45%, #1a2236 100%);
    color: #ffffff;
    padding: 32px 30px;
    border-radius: 16px;
    margin-bottom: 22px;
    box-shadow: 0 12px 30px rgba(0,0,0,0.45);
    text-align: center;
    position: relative;
    overflow: hidden;
    border: 1px solid rgba(255,255,255,0.08);
}

.activist-sim-header::before {
    content: '';
    position: absolute;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: radial-gradient(circle, rgba(255,255,255,0.06) 0%, transparent 60%);
    pointer-events: none;
}

.activist-sim-header-icon {
    font-size: 2.6rem;
    margin-bottom: 8px;
}

.activist-sim-header h1 {
    font-size: 1.9rem;
    font-weight: 800;
    margin-bottom: 6px;
    letter-spacing: 0.3px;
}

.activist-sim-header p {
    font-size: 1rem;
    opacity: 0.88;
    margin: 0 0 14px 0;
}

.activist-sim-clock {
    display: inline-block;
    background: rgba(0,0,0,0.35);
    border: 1px solid rgba(255,255,255,0.18);
    border-radius: 999px;
    padding: 6px 18px;
    font-size: 0.92rem;
    font-weight: 600;
    letter-spacing: 0.4px;
}

.activist-sim-clock #deadlineDisplay {
    color: #ffd24a;
    font-weight: 800;
    margin: 0 4px;
}

.activist-sim-period-counter {
    text-align: center;
    font-size: 1.05rem;
    color: #b8c4dc;
    margin-bottom: 22px;
    font-weight: 600;
}

.activist-sim-period-counter span {
    margin: 0 3px;
}

.activist-sim-period-counter #currentDay,
.activist-sim-period-counter #maxPeriods {
    color: #ff6b81;
    font-weight: 800;
}

.activist-sim-round-name {
    display: inline-block;
    margin-left: 10px;
    padding: 3px 14px;
    background: rgba(177,24,43,0.25);
    border: 1px solid rgba(255,107,129,0.4);
    border-radius: 999px;
    color: #ffc2cc;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
}

/* ---- KPI cards ---- */
.activist-sim-kpi-section {
    margin-bottom: 22px;
}

.activist-sim-kpi-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 16px;
}

.activist-sim-kpi-cards-secondary {
    grid-template-columns: repeat(3, 1fr);
    margin-bottom: 0;
}

.activist-sim-kpi-card {
    background: linear-gradient(160deg, #1e2740 0%, #19223a 100%);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px;
    padding: 18px 18px 20px;
    box-shadow: 0 6px 18px rgba(0,0,0,0.3);
    transition: transform 0.18s ease, box-shadow 0.18s ease;
}

.activist-sim-kpi-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 10px 26px rgba(0,0,0,0.45);
}

.activist-kpi-hero {
    border: 1px solid rgba(74,222,128,0.35);
    background: linear-gradient(160deg, #16321f 0%, #19223a 100%);
}

.activist-sim-kpi-label {
    font-size: 0.82rem;
    color: #9fb0cc;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    margin-bottom: 8px;
    font-weight: 600;
}

.activist-sim-kpi-value {
    font-size: 2.6rem;
    font-weight: 800;
    color: #ffffff;
    line-height: 1.05;
}

.activist-kpi-hero .activist-sim-kpi-value {
    color: #4ade80;
}

.activist-bad {
    color: #ff6b81 !important;
}

.activist-kpi-small .activist-sim-kpi-value {
    font-size: 1.5rem;
}

.activist-sim-kpi-sub {
    font-size: 0.74rem;
    color: #7e8caa;
    margin-top: 8px;
    line-height: 1.3;
}

.activist-sim-kpi-bar-bg {
    height: 8px;
    background: rgba(255,255,255,0.1);
    border-radius: 6px;
    margin-top: 12px;
    overflow: hidden;
}

.activist-sim-kpi-bar-fill {
    height: 100%;
    border-radius: 6px;
    transition: width 0.5s ease;
}

.activist-rep-fill { background: linear-gradient(90deg, #22c55e, #4ade80); }
.activist-campaign-fill { background: linear-gradient(90deg, #f97316, #ff6b81); }
.activist-investor-fill { background: linear-gradient(90deg, #3b82f6, #60a5fa); }
.activist-gov-fill { background: linear-gradient(90deg, #a855f7, #c084fc); }

/* ---- Briefing ---- */
.activist-sim-briefing {
    background: linear-gradient(160deg, #1c2438 0%, #18203400 100%), #1a2236;
    border: 1px solid rgba(255,255,255,0.08);
    border-left: 4px solid #ff6b81;
    border-radius: 14px;
    padding: 22px 24px;
    margin-bottom: 22px;
    box-shadow: 0 6px 18px rgba(0,0,0,0.3);
}

.activist-sim-briefing h3 {
    font-size: 1.15rem;
    font-weight: 700;
    margin-bottom: 14px;
    color: #ffd24a;
}

.activist-sim-briefing-text {
    font-size: 0.96rem;
    line-height: 1.65;
    color: #d6deee;
}

.activist-sim-briefing-text strong {
    color: #ffffff;
}

.activist-sim-event-alert {
    margin-top: 16px;
    padding: 14px 16px;
    background: rgba(249,115,22,0.14);
    border: 1px solid rgba(249,115,22,0.45);
    border-radius: 10px;
    color: #ffd9b0;
    font-size: 0.92rem;
    line-height: 1.55;
}

/* ---- Controls ---- */
.activist-sim-controls {
    background: linear-gradient(160deg, #1e2740 0%, #19223a 100%);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px;
    padding: 24px;
    margin-bottom: 22px;
    box-shadow: 0 6px 18px rgba(0,0,0,0.3);
}

.activist-sim-controls h3 {
    font-size: 1.2rem;
    font-weight: 700;
    margin-bottom: 6px;
    color: #ffffff;
}

.activist-sim-decisions-note {
    font-size: 0.86rem;
    color: #9fb0cc;
    margin-bottom: 18px;
    font-style: italic;
}

.activist-sim-input-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 18px 22px;
}

.activist-sim-input-group {
    display: flex;
    flex-direction: column;
}

.activist-sim-input-group label {
    font-size: 0.9rem;
    font-weight: 600;
    color: #cdd7ec;
    margin-bottom: 7px;
}

.activist-sim-container .form-control {
    background-color: #11192c;
    color: #f0f4fc;
    border: 1px solid rgba(255,255,255,0.16);
    border-radius: 8px;
    padding: 10px 12px;
    font-size: 0.95rem;
}

.activist-sim-container .form-control:focus {
    border-color: #ff6b81;
    box-shadow: 0 0 0 3px rgba(255,107,129,0.18);
    background-color: #11192c;
    color: #f0f4fc;
    outline: none;
}

.activist-sim-container select.form-control {
    background-color: #11192c;
    color: #f0f4fc;
}

.activist-sim-container select.form-control option {
    background-color: #11192c;
    color: #f0f4fc;
}

.activist-sim-hint {
    font-size: 0.76rem;
    color: #7e8caa;
    margin-top: 6px;
    line-height: 1.35;
}

.activist-sim-btn-row {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-top: 22px;
    flex-wrap: wrap;
}

.activist-sim-container .btn-primary {
    background: linear-gradient(135deg, #b1182b 0%, #ff6b81 100%);
    border: none;
    font-weight: 700;
    letter-spacing: 0.4px;
    padding: 12px 30px;
    border-radius: 10px;
    box-shadow: 0 6px 16px rgba(177,24,43,0.4);
}

.activist-sim-container .btn-primary:hover {
    background: linear-gradient(135deg, #c81e33 0%, #ff859a 100%);
}

.activist-sim-container .btn-outline-secondary {
    color: #b8c4dc;
    border-color: rgba(255,255,255,0.25);
    border-radius: 10px;
}

.activist-sim-container .btn-outline-secondary:hover {
    background: rgba(255,255,255,0.08);
    color: #ffffff;
}

/* ---- Charts ---- */
.activist-sim-charts {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 18px;
    margin-bottom: 22px;
}

.activist-sim-chart-box {
    background: #f7f9fc;
    border-radius: 14px;
    padding: 16px;
    box-shadow: 0 6px 18px rgba(0,0,0,0.3);
    min-height: 320px;
}

/* ---- History ---- */
.activist-sim-history {
    background: linear-gradient(160deg, #1e2740 0%, #19223a 100%);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px;
    padding: 22px 24px;
    box-shadow: 0 6px 18px rgba(0,0,0,0.3);
}

.activist-sim-history h3 {
    font-size: 1.1rem;
    font-weight: 700;
    margin-bottom: 14px;
    color: #ffffff;
}

.activist-sim-history table {
    color: #d6deee;
    margin-bottom: 0;
}

.activist-sim-history .table-striped tbody tr:nth-of-type(odd) {
    background-color: rgba(255,255,255,0.04);
}

.activist-sim-history th {
    color: #9fb0cc;
    border-color: rgba(255,255,255,0.12);
    font-size: 0.82rem;
    text-transform: uppercase;
    letter-spacing: 0.4px;
}

.activist-sim-history td {
    border-color: rgba(255,255,255,0.08);
    font-size: 0.88rem;
}

/* ---- Responsive ---- */
@media (max-width: 768px) {
    .activist-sim-container {
        padding: 12px;
    }
    .activist-sim-header h1 {
        font-size: 1.45rem;
    }
    .activist-sim-kpi-cards,
    .activist-sim-kpi-cards-secondary {
        grid-template-columns: 1fr;
    }
    .activist-sim-input-grid {
        grid-template-columns: 1fr;
    }
    .activist-sim-charts {
        grid-template-columns: 1fr;
    }
    .activist-sim-kpi-value {
        font-size: 2.1rem;
    }
}


/* FIX v1.1.0 — completion / board-debrief screen */
.ag-completion { padding: 10px 6px; text-align: center; }
.ag-completion-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #64748b; margin-bottom: 6px; }
.ag-completion-verdict { font-size: 20px; font-weight: 700; color: #0f172a; margin-bottom: 8px; }
.ag-completion-score { font-size: 16px; color: #0f172a; margin-bottom: 14px; }
.ag-completion-score strong { color: #b91c1c; }
.ag-completion-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.ag-completion-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 8px 12px; background: #f1f5f9; border-radius: 8px; min-width: 104px; }
.ag-completion-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #64748b; }
.ag-completion-metric strong { font-size: 16px; color: #0f172a; }
.ag-completion-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 680px; text-align: left; }
.ag-completion-insights li { padding: 9px 13px; margin-bottom: 7px; background: #fef2f2; border-left: 3px solid #b91c1c; border-radius: 4px; color: #1e293b; font-size: 13px; }

js:
(function() {
    'use strict';

    class ActivistGateAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'The Activist at the Gate';
            this.version = '1.1.0';

            // The "truth" of the adversary, hidden from the team. A Tier-1 health NGO with a
            // 1.4M-follower network and ESG investors behind it = very high resources. Its ask
            // (change a field practice, hold the firm to its own Charter) = reformist, not absolutist.
            this.TRUE_RESOURCES = 85;
            this.TRUE_RADICALISM = 30;

            // Concession profiles: each buys de-escalation, costs CHF, and carries a precedent risk.
            // deescalation = how much it cuts campaign intensity; cost = one-off + recurring CHF (M);
            // precedent = strategic ground ceded to future challengers; repBoost = reputational signal.
            this.CONCESSIONS = {
                none:       { deescalation: -6,  cost: 0,    precedent: 0,  repBoost: -8, credible: false },
                reaffirm:   { deescalation: 12,  cost: 1,    precedent: 5,  repBoost: 10, credible: true  },
                audit:      { deescalation: 22,  cost: 2.5,  precedent: 8,  repBoost: 16, credible: true  },
                monitor:    { deescalation: 30,  cost: 6,    precedent: 18, repBoost: 18, credible: true  },
                pause:      { deescalation: 34,  cost: 40,   precedent: 28, repBoost: 14, credible: true  },
                moratorium: { deescalation: 40,  cost: 95,   precedent: 55, repBoost: 12, credible: true  }
            };

            this.ROUNDS = [
                {
                    nameEn: 'Read the Adversary',
                    nameEs: 'Lea al Adversario',
                    briefingEn: `<strong>14 March 2026 — one week before the AGM.</strong> A respected international health NGO, three national consumer groups and a 1.4-million-follower advocacy network have launched <em>“Formula First, Babies Last.”</em> Their 40-page report alleges Helvetia sales reps in two West African markets handed out free formula samples and ran “baby clubs” — practices the report says breach both the WHO Code and Helvetia's own published <strong>Responsible Marketing Charter</strong>.<br><br>Within 72 hours: <strong>22 million impressions</strong>, three Tier-1 outlets, a <strong>180,000-signature</strong> petition. Two institutional holders (9% combined) threaten an AGM resolution; a CHF-3bn pension fund places the stock “under review”; a grocery chain worth <strong>CHF 168M/year</strong> wants written assurance in 21 days.<br><br>Before you react, <strong>profile the coalition</strong> using Yaziji's resources × radicalism filter. How resourced are they — legitimacy, money, network, media reach? How radical is the ask — reformist (change a practice) or absolutist (no marketing at all)? Set your two reads. An accurate map is what lets you pick the right posture next round; a wrong map is how teams pick the wrong posture entirely.`,
                    briefingEs: `<strong>14 de marzo de 2026 — una semana antes de la Junta.</strong> Una respetada ONG internacional de salud, tres grupos de consumidores y una red de 1,4 millones de seguidores han lanzado <em>“Fórmula Primero, Bebés Después.”</em> Su informe de 40 páginas alega que representantes de Helvetia en dos mercados de África Occidental repartieron muestras gratuitas de fórmula y operaron “clubes de bebés” — prácticas que, según el informe, violan tanto el Código de la OMS como la propia <strong>Carta de Marketing Responsable</strong> publicada por Helvetia.<br><br>En 72 horas: <strong>22 millones de impresiones</strong>, tres medios Tier-1, una petición con <strong>180.000 firmas</strong>. Dos inversores institucionales (9% combinado) amenazan con una resolución en la Junta; un fondo de pensiones de CHF 3.000M pone la acción “bajo revisión”; una cadena de supermercados que vale <strong>CHF 168M/año</strong> exige garantías por escrito en 21 días.<br><br>Antes de reaccionar, <strong>perfile a la coalición</strong> con el filtro recursos × radicalismo de Yaziji. ¿Con cuántos recursos cuentan — legitimidad, dinero, red, alcance mediático? ¿Qué tan radical es la demanda — reformista (cambiar una práctica) o absolutista (ningún marketing)? Fije sus dos lecturas. Un mapa preciso le permite elegir la postura correcta la próxima ronda; un mapa erróneo es cómo los equipos eligen la postura equivocada por completo.`,
                    eventEn: null,
                    eventEs: null
                },
                {
                    nameEn: 'The Posture Decision',
                    nameEs: 'La Decisión de Postura',
                    briefingEn: `Your adversary map is on the wall. Now choose Helvetia's <strong>primary non-market posture</strong> and justify it against the reputational-risk constraint.<br><br><strong>Resist</strong> — defend the practices as “locally legal,” contest the report. Preserves short-term emerging-market revenue, but the activists aren't quoting West African law — they're quoting <em>your own Charter</em>. Against a high-resource, reformist coalition this risks the AGM and the grocery contract.<br><strong>Engage</strong> — acknowledge, investigate, correct. Protects reputation and concedes the Charter was breached. Fits a reformist challenger with a valid claim.<br><strong>Partner</strong> — invite the credible health NGO into a monitoring arrangement. Can neutralize the campaign but cedes control — and is only safe with <em>bounded</em> terms (scope, sunset, decision rights). Open-ended partnership hands the activist a key to the building.<br><br>Match the posture to the adversary's <em>true</em> profile, not the firm's reflex. Set your posture and, if partnering, your bounding.`,
                    briefingEs: `Su mapa del adversario está en la pizarra. Ahora elija la <strong>postura no-mercado principal</strong> de Helvetia y justifíquela frente a la restricción de riesgo reputacional.<br><br><strong>Resistir</strong> — defender las prácticas como “localmente legales”, refutar el informe. Preserva ingresos a corto plazo en mercados emergentes, pero los activistas no citan la ley de África Occidental — citan <em>su propia Carta</em>. Frente a una coalición reformista de altos recursos, esto arriesga la Junta y el contrato de supermercados.<br><strong>Comprometerse (Engage)</strong> — reconocer, investigar, corregir. Protege la reputación y concede que la Carta fue incumplida. Encaja con un retador reformista con una demanda válida.<br><strong>Asociarse (Partner)</strong> — invitar a la ONG de salud creíble a un acuerdo de monitoreo. Puede neutralizar la campaña pero cede control — y solo es seguro con términos <em>acotados</em> (alcance, vencimiento, derechos de decisión). Una asociación abierta entrega al activista una llave del edificio.<br><br>Empareje la postura con el perfil <em>real</em> del adversario, no con el reflejo de la empresa. Fije su postura y, si se asocia, su acotamiento.`,
                    eventEn: `⚠️ <strong>Pressure spikes:</strong> A Tier-1 European outlet runs a front-page comparison of Helvetia's Charter wording against the alleged field conduct, headlined “Their Own Words.” A flat denial now would be quoted back at the AGM.`,
                    eventEs: `⚠️ <strong>La presión se dispara:</strong> Un medio europeo Tier-1 publica en portada una comparación entre el texto de la Carta de Helvetia y la conducta de campo alegada, titulada “Sus Propias Palabras.” Una negación rotunda ahora sería citada en su contra en la Junta.`
                },
                {
                    nameEn: 'Set the Concession',
                    nameEs: 'Fije la Concesión',
                    briefingEn: `Now set a single, concrete <strong>concession</strong> — calibrated, not capitulating. The spectrum: re-affirm the Charter with named accountability; an <strong>independent audit (CHF 2.5M)</strong>; a <strong>third-party NGO monitoring</strong> partnership; a <strong>regional marketing pause (~CHF 40M/year)</strong>; or a <strong>group-wide sample moratorium</strong>.<br><br>Too little inflames the campaign. Too much hands activists a precedent every future challenger will cite and dents the franchise for years. A group-wide moratorium buys silence this week — but it is roughly CHF 40M+/year and a precedent forever. Size the concession to the <em>de-escalation it actually buys</em>, not to fear, and bound it so it does not become hostage to every future demand. Then ask: where is the line beyond which Helvetia will not go?`,
                    briefingEs: `Ahora fije una sola <strong>concesión</strong> concreta — calibrada, no capituladora. El espectro: re-afirmar la Carta con rendición de cuentas nominada; una <strong>auditoría independiente (CHF 2,5M)</strong>; una asociación de <strong>monitoreo por un tercero (ONG)</strong>; una <strong>pausa regional de marketing (~CHF 40M/año)</strong>; o una <strong>moratoria de muestras a nivel de grupo</strong>.<br><br>Muy poco inflama la campaña. Demasiado entrega a los activistas un precedente que todo retador futuro citará y daña la franquicia por años. Una moratoria de grupo compra silencio esta semana — pero cuesta cerca de CHF 40M+/año y un precedente para siempre. Dimensione la concesión a la <em>desescalada que realmente compra</em>, no al miedo, y acótela para que no quede rehén de cada demanda futura. Luego pregunte: ¿dónde está la línea que Helvetia no cruzará?`,
                    eventEn: `📊 <strong>Investor signal:</strong> The lead ESG holder privately says it wants “credible, verifiable correction — not theatre, and not a blank cheque.” A calibrated, bounded concession reads as competence; an over-concession reads as panic.`,
                    eventEs: `📊 <strong>Señal de inversores:</strong> El principal inversor ESG dice en privado que quiere “corrección creíble y verificable — ni teatro, ni cheque en blanco.” Una concesión calibrada y acotada se lee como competencia; una sobre-concesión se lee como pánico.`
                },
                {
                    nameEn: 'Face the AGM',
                    nameEs: 'Enfrente la Junta',
                    briefingEn: `🏛️ <strong>THE AGM.</strong> You face the lead institutional investor and a journalist. They will weigh your posture, your concession — and, decisively, whether this crisis left a <strong>standing capability</strong> behind or was just survived.<br><br>Set your <strong>forward governance commitment</strong>. Quarterly Charter reporting closes the say-do gap. Revised field incentives (de-linking bonuses from volume) fix the root cause the reps cited. A stakeholder advisory panel institutionalises the relationship. Do nothing and the reps still earn bonuses on volume — when the next coalition forms, you are exactly as exposed.<br><br>A resolution passes against you unless your reputation has recovered, the campaign has cooled, and investors see real governance. Make the crisis build something.`,
                    briefingEs: `🏛️ <strong>LA JUNTA.</strong> Enfrenta al principal inversor institucional y a un periodista. Pesarán su postura, su concesión — y, de forma decisiva, si esta crisis dejó una <strong>capacidad permanente</strong> o solo fue sobrevivida.<br><br>Fije su <strong>compromiso de gobernanza prospectivo</strong>. El reporte trimestral de la Carta cierra la brecha decir-hacer. Incentivos de campo revisados (desligar bonos del volumen) corrigen la causa raíz que citaron los representantes. Un panel asesor de partes interesadas institucionaliza la relación. No haga nada y los representantes seguirán cobrando bonos por volumen — cuando se forme la próxima coalición, estará igual de expuesto.<br><br>Una resolución pasa en su contra salvo que su reputación se haya recuperado, la campaña se haya enfriado y los inversores vean gobernanza real. Haga que la crisis construya algo.`,
                    eventEn: `🎙️ <strong>Hostile question:</strong> “You published a Charter, then your reps broke it. Why should this AGM believe any pledge you make today?” Your governance commitment is the only credible answer.`,
                    eventEs: `🎙️ <strong>Pregunta hostil:</strong> “Publicaron una Carta y luego sus representantes la incumplieron. ¿Por qué debería esta Junta creer cualquier compromiso que hagan hoy?” Su compromiso de gobernanza es la única respuesta creíble.`
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    reputation: 72,        // the franchise stock (0-100)
                    campaign: 68,          // activist intensity (0-100, lower better)
                    investor: 54,          // investor confidence (0-100)
                    governance: 20,        // standing non-market capability (0-100)
                    financialImpact: 0,    // cumulative CHF M lost (negative wealth)
                    groceryStatus: 'risk', // 'risk' | 'retained' | 'lost'
                    outcome: 'unfolding',  // 'unfolding' | 'survived' | 'defeated'
                    mapAccuracy: 0,        // accuracy of resources/radicalism read (0-100)
                    precedentLoad: 0,      // cumulative strategic ground ceded
                    reputationHistory: [],
                    campaignHistory: [],
                    investorHistory: [],
                    governanceHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    resources: 50,
                    radicalism: 50,
                    posture: 'engage',
                    concession: 'audit',
                    scope: 3,
                    governance: 2
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var resEl = document.getElementById('resourcesInput');
            var radEl = document.getElementById('radicalismInput');
            var postureEl = document.getElementById('postureInput');
            var concEl = document.getElementById('concessionInput');
            var scopeEl = document.getElementById('scopeInput');
            var govEl = document.getElementById('governanceInput');

            if (resEl) decisions.resources = parseInt(resEl.value, 10);
            if (radEl) decisions.radicalism = parseInt(radEl.value, 10);
            if (postureEl) decisions.posture = postureEl.value;
            if (concEl) decisions.concession = concEl.value;
            if (scopeEl) decisions.scope = parseInt(scopeEl.value, 10);
            if (govEl) decisions.governance = parseInt(govEl.value, 10);

            if (!Number.isFinite(decisions.resources) || decisions.resources < 0 || decisions.resources > 100) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('resources_warning'), 'warning');
                return false;
            }
            if (!Number.isFinite(decisions.radicalism) || decisions.radicalism < 0 || decisions.radicalism > 100) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('radicalism_warning'), 'warning');
                return false;
            }
            if (['resist', 'engage', 'partner'].indexOf(decisions.posture) === -1) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('posture_warning'), 'warning');
                return false;
            }
            if (!this.CONCESSIONS[decisions.concession]) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('concession_warning'), 'warning');
                return false;
            }
            if (!Number.isFinite(decisions.scope) || decisions.scope < 1 || decisions.scope > 5) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('scope_warning'), 'warning');
                return false;
            }
            if (!Number.isFinite(decisions.governance) || decisions.governance < 0 || decisions.governance > 5) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('governance_warning'), 'warning');
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;

            // ---- Adversary-map accuracy (scored every round, dominates Round 1) ----
            var resErr = Math.abs(d.resources - this.TRUE_RESOURCES);
            var radErr = Math.abs(d.radicalism - this.TRUE_RADICALISM);
            var mapAccuracy = Math.max(0, Math.round(100 - (resErr + radErr) / 2));
            ds.mapAccuracy = mapAccuracy;

            // A correct read = high resources + reformist. That read should point to Engage/bounded Partner.
            var readsReformist = d.radicalism <= 50;
            var readsHighResource = d.resources >= 60;

            // ---- Posture fit vs the TRUE profile ----
            // Truth: high-resource + reformist + valid claim quoting your own Charter.
            // Engage = best. Partner = good only if bounded. Resist = the Charter trap = worst.
            var postureRep = 0, postureCampaign = 0, postureInvestor = 0, postureGov = 0, postureFin = 0;
            var scopeNorm = (d.scope - 1) / 4; // 0..1 bounding quality

            if (d.posture === 'resist') {
                // Defending with law against your own words. Short-term EM revenue kept, everything else burns.
                postureRep = -22;
                postureCampaign = 16;     // inflames
                postureInvestor = -18;
                postureGov = 0;
                postureFin = 8;           // protects ~CHF 8M short-term EM revenue this round
            } else if (d.posture === 'engage') {
                postureRep = 14;
                postureCampaign = -14;
                postureInvestor = 12;
                postureGov = 4;
                postureFin = -2;          // small cost of acknowledging/correcting
            } else if (d.posture === 'partner') {
                // Strong de-escalation, but unbounded partnership cedes control (rep & investor penalty).
                postureRep = 8 + scopeNorm * 12;          // bounded partner reads as confident
                postureCampaign = -20;                    // neutralizes the campaign most
                postureInvestor = -4 + scopeNorm * 14;    // open-ended worries investors; bounded reassures
                postureGov = 6 + scopeNorm * 6;
                postureFin = -3;
                ds.precedentLoad += Math.round((1 - scopeNorm) * 18); // open-ended = ceded ground
            }

            // Penalty for picking a posture that contradicts a correct read, or acting on a wrong map.
            var fitPenaltyRep = 0;
            if (d.posture === 'resist' && readsReformist && readsHighResource) {
                // You read them correctly (reformist, high-resource) and STILL chose to fight your own words.
                fitPenaltyRep -= 10;
                postureCampaign += 6;
            }
            if (mapAccuracy < 45) {
                // Acting on a badly wrong map costs credibility regardless of posture.
                fitPenaltyRep -= 6;
                postureInvestor -= 6;
            }

            // ---- Concession calibration ----
            var c = this.CONCESSIONS[d.concession];
            var concRep = c.repBoost;
            var concCampaign = -c.deescalation;
            var concInvestor = 0;
            ds.precedentLoad += c.precedent;

            // Recurring-cost concessions (pause ~40/yr, moratorium ~95) are franchise-destroying if fear-driven.
            var concFin = -c.cost;
            // Over-concession: a huge concession against a merely reformist ask reads as panic and dents franchise.
            if (d.concession === 'moratorium' || d.concession === 'pause') {
                if (this.TRUE_RADICALISM <= 40) {
                    concRep -= 10;        // over-paid: franchise dent + precedent
                    concInvestor -= 8;    // investors read panic
                }
            }
            // Under-concession against a high-resource campaign leaves the heat on.
            if ((d.concession === 'none') && readsHighResource) {
                concCampaign += 8;
                concInvestor -= 6;
            }
            // A credible concession plus an Engage/Partner posture compounds (coherent story).
            if (c.credible && (d.posture === 'engage' || d.posture === 'partner')) {
                concInvestor += 6;
            }
            // A concession stapled to a Resist posture reads as incoherent (offering while denying).
            if (c.credible && d.posture === 'resist') {
                concRep -= 6;
                concInvestor -= 4;
            }

            // ---- Forward governance commitment (decisive in Round 4) ----
            var govLevel = d.governance; // 0..5
            var govRep = govLevel * 2.5;
            var govCampaign = -govLevel * 2;
            var govInvestor = govLevel * 3;
            var govBuild = govLevel * 14; // capability built
            // Governance only fully "lands" when it includes the root-cause fix (level >=3 de-links incentives).
            var rootCauseFixed = govLevel >= 3;
            if (!rootCauseFixed && period === 4) {
                govInvestor -= 6; // investors note the reps still earn on volume
            }
            // Cost of building governance machinery (modest, recurring).
            var govFin = -(govLevel * 0.8);

            // ---- Apply deltas (weighted so each round's headline lever dominates) ----
            // Round weighting emphasises the round's focal decision but keeps the model continuous.
            var wMap = period === 1 ? 1.0 : 0.25;
            var wPosture = period === 2 ? 1.0 : 0.4;
            var wConcession = period === 3 ? 1.0 : 0.4;
            var wGov = period === 4 ? 1.0 : 0.35;

            // Round 1: an accurate map itself nudges reputation/governance (clear-eyed start).
            var mapRep = (mapAccuracy - 50) * 0.16 * wMap;
            var mapGov = (mapAccuracy - 40) * 0.10 * wMap;

            var dRep = mapRep + (postureRep + fitPenaltyRep) * wPosture + concRep * wConcession + govRep * wGov;
            var dCampaign = postureCampaign * wPosture + concCampaign * wConcession + govCampaign * wGov - (mapAccuracy > 70 ? 3 : 0);
            var dInvestor = (postureInvestor) * wPosture + concInvestor * wConcession + govInvestor * wGov;
            var dGov = mapGov + postureGov * wPosture + govBuild * wGov;
            var dFin = postureFin * wPosture + concFin * (wConcession + 0.0) + govFin * wGov;

            ds.reputation = Math.max(0, Math.min(100, Math.round(ds.reputation + dRep)));
            ds.campaign = Math.max(0, Math.min(100, Math.round(ds.campaign + dCampaign)));
            ds.investor = Math.max(0, Math.min(100, Math.round(ds.investor + dInvestor)));
            ds.governance = Math.max(0, Math.min(100, Math.round(ds.governance + dGov)));
            ds.financialImpact = Math.round((ds.financialImpact + dFin) * 10) / 10;

            // ---- Grocery contract resolution: needs a credible, coherent response by Round 3+. ----
            if (period >= 3) {
                var credibleResponse = (d.posture !== 'resist') && c.credible && ds.reputation >= 50 && ds.campaign <= 60;
                if (credibleResponse) {
                    ds.groceryStatus = 'retained';
                } else if (ds.reputation < 40 || ds.campaign > 75) {
                    ds.groceryStatus = 'lost';
                    if (period === 3) {
                        ds.financialImpact = Math.round((ds.financialImpact - 168) * 10) / 10; // lose the CHF 168M/yr contract
                    }
                } else {
                    ds.groceryStatus = 'risk';
                }
            }

            // ---- AGM outcome (Round 4): resolution survives only with recovered rep, cooled campaign, real governance. ----
            if (period === 4) {
                var survived = ds.reputation >= 55 && ds.campaign <= 45 && ds.investor >= 50 && ds.governance >= 45;
                ds.outcome = survived ? 'survived' : 'defeated';
                if (!survived) {
                    // Share-price overhang 4-7% of franchise; analyst estimate if unresolved.
                    var overhangPct = 4 + Math.min(3, Math.round((75 - ds.investor) / 10));
                    var overhang = Math.round(1100 * (overhangPct / 100)); // % of CHF 1.1bn infant-nutrition franchise
                    ds.financialImpact = Math.round((ds.financialImpact - overhang) * 10) / 10;
                }
            } else {
                ds.outcome = 'unfolding';
            }

            // ---- History ----
            ds.reputationHistory.push(ds.reputation);
            ds.campaignHistory.push(ds.campaign);
            ds.investorHistory.push(ds.investor);
            ds.governanceHistory.push(ds.governance);

            this._updateBars(ds);

            var self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 500);

            // v1.1.0 FIX A — expose a per-round composite on the reporting paths
            // (express_resolveDomainScore reads domainState.score / performance.overallScore;
            // trend reads results.score/overallScore). Same weights as getPerformanceSummary.
            var _c = Math.round(ds.reputation * 0.30 + (100 - ds.campaign) * 0.20 + ds.investor * 0.20 + ds.governance * 0.20 + Math.max(0, 100 - (ds.precedentLoad || 0)) * 0.10);
            _c = Math.max(0, Math.min(100, _c));
            ds.score = _c;
            ds.performance = { overallScore: _c };
            return {
                period: period,
                score: _c,
                overallScore: _c,
                resources: d.resources,
                radicalism: d.radicalism,
                posture: d.posture,
                concession: d.concession,
                scope: d.scope,
                governance: d.governance,
                mapAccuracy: mapAccuracy,
                reputation: ds.reputation,
                campaign: ds.campaign,
                investor: ds.investor,
                governanceScore: ds.governance,
                financialImpact: ds.financialImpact,
                precedentLoad: ds.precedentLoad,
                groceryStatus: ds.groceryStatus,
                outcome: ds.outcome
            };
        }

        _updateBars(ds) {
            var rep = document.getElementById('reputationBar');
            var camp = document.getElementById('campaignBar');
            var inv = document.getElementById('investorBar');
            var gov = document.getElementById('governanceBar');
            if (rep) rep.style.width = ds.reputation + '%';
            if (camp) camp.style.width = ds.campaign + '%';
            if (inv) inv.style.width = ds.investor + '%';
            if (gov) gov.style.width = ds.governance + '%';
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var lang = 'en';
            try {
                lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : 'en';
            } catch (e) { lang = 'en'; }

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                briefEl.innerHTML = lang === 'es' ? round.briefingEs : round.briefingEn;
            }

            var nameEl = document.getElementById('roundNameDisplay');
            if (nameEl) {
                nameEl.textContent = lang === 'es' ? round.nameEs : round.nameEn;
            }

            var noteEl = document.getElementById('liveLeversNote');
            if (noteEl) {
                var noteKey = 'levers_note_r' + (idx + 1);
                try { noteEl.textContent = window.mySimulation.t(noteKey); } catch (e) {}
            }

            var eventEl = document.getElementById('eventAlert');
            if (eventEl) {
                var eventText = lang === 'es' ? round.eventEs : round.eventEn;
                if (eventText) {
                    eventEl.innerHTML = eventText;
                    eventEl.style.display = 'block';
                } else {
                    eventEl.style.display = 'none';
                }
            }
        }

