        formatCompletionMessage(summary) {
            var t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            var score = (summary.totalScore != null) ? summary.totalScore : 0;
            var grade = summary.gradeKey ? t(summary.gradeKey) : '';
            var insights = summary.insights || [];
            var items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            var metric = function (label, val) {
                return '<div class="ag-completion-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            var metrics = ''
                + metric(t('comp_rep_label'), (summary.reputation != null ? summary.reputation : '-'))
                + metric(t('comp_camp_label'), (summary.campaign != null ? summary.campaign : '-'))
                + metric(t('comp_inv_label'), (summary.investor != null ? summary.investor : '-'))
                + metric(t('comp_gov_label'), (summary.governance != null ? summary.governance : '-'))
                + metric(t('comp_fin_label'), (summary.financialImpact != null ? summary.financialImpact : '-'));
            return ''
                + '<div class="ag-completion">'
                +   '<div class="ag-completion-heading">' + t('comp_heading') + '</div>'
                +   '<div class="ag-completion-verdict">' + grade + '</div>'
                +   '<div class="ag-completion-score">' + t('comp_score_label') + ': <strong>' + score + '</strong> / 100</div>'
                +   '<div class="ag-completion-metrics">' + metrics + '</div>'
                +   (items ? '<ul class="ag-completion-insights">' + items + '</ul>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : function (k) { return k; };
            var last = history[history.length - 1];
            var r = last.results || {};

            var rep = r.reputation || 0;
            var camp = r.campaign || 0;
            var inv = r.investor || 0;
            var gov = r.governanceScore || 0;
            var fin = r.financialImpact || 0;
            var precedent = r.precedentLoad || 0;

            // Composite: reputation preserved (30%), campaign cooled (20%), investor (20%),
            // governance capability built (20%), franchise/precedent discipline (10%).
            var repScore = rep * 0.30;
            var campScore = (100 - camp) * 0.20;
            var invScore = inv * 0.20;
            var govScore = gov * 0.20;
            var disciplineScore = Math.max(0, 100 - precedent) * 0.10;
            var totalScore = Math.round(repScore + campScore + invScore + govScore + disciplineScore);

            // Penalise a financial bloodbath regardless of optics.
            if (fin <= -150) totalScore = Math.max(0, totalScore - 12);

            var bonus = (r.outcome === 'survived') ? 1.1 : 1.0;
            totalScore = Math.min(100, Math.round(totalScore * bonus));

            var performance = 'Reactive Operator';
            if (totalScore >= 78 && r.outcome === 'survived') performance = 'Non-Market Strategist';
            else if (totalScore >= 62) performance = 'Capable Corporate-Affairs Lead';
            else if (totalScore >= 45) performance = 'Developing Crisis Manager';

            var insights = [];

            // Map / posture read-back
            var maps = history.map(function(h){ return (h.results && h.results.mapAccuracy) || 0; });
            var avgMap = Math.round(maps.reduce(function(a,b){return a+b;},0) / maps.length);
            if (avgMap >= 75) insights.push(t('ins_map_good'));
            else insights.push(t('ins_map_bad'));

            // Charter trap
            var resisted = history.some(function(h){ return h.results && h.results.posture === 'resist'; });
            if (resisted) insights.push(t('ins_charter'));

            // Over-concession
            var overConceded = history.some(function(h){ return h.results && (h.results.concession === 'moratorium' || h.results.concession === 'pause'); });
            if (overConceded && precedent >= 35) insights.push(t('ins_overconcede'));

            // Governance follow-through
            if (gov >= 60) insights.push(t('ins_gov_good'));
            else insights.push(t('ins_gov_bad'));

            // Grocery + financial
            if (r.groceryStatus === 'retained') insights.push(t('ins_grocery_kept'));
            else if (r.groceryStatus === 'lost') insights.push(t('ins_grocery_lost'));

            var _gk = (totalScore >= 78 && r.outcome === 'survived') ? 'grade_strategist' : totalScore >= 62 ? 'grade_capable' : totalScore >= 45 ? 'grade_developing' : 'grade_reactive';
            if (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) {
                window.mySimulation.state.domainState.score = totalScore;
                window.mySimulation.state.domainState.performance = { overallScore: totalScore, grade: t(_gk) };
            }
            return {
                totalScore: totalScore,
                score: totalScore,
                gradeKey: _gk,
                reputation: rep,
                campaign: camp,
                investor: inv,
                governance: gov,
                financialImpact: fin,
                precedentLoad: precedent,
                avgMapAccuracy: avgMap,
                outcome: r.outcome,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.outcome === 'survived') return window.mySimulation.t('hint_survived');
            if (results.outcome === 'defeated') return window.mySimulation.t('hint_defeated');
            if (results.posture === 'resist') return window.mySimulation.t('hint_charter_trap');
            if (results.concession === 'moratorium' || results.concession === 'pause') return window.mySimulation.t('hint_overconcession');
            if (results.mapAccuracy < 50) return window.mySimulation.t('hint_bad_map');
            if (results.campaign > 60) return window.mySimulation.t('hint_high_campaign');
            if (state.currentPeriod >= 3 && results.governanceScore < 40) return window.mySimulation.t('hint_build_governance');
            return window.mySimulation.t('hint_good_progress');
        }

        getHistoryTableConfig() {
            var self = this;
            return [
                { key: 'results.posture', label: 'Posture', i18nKey: 'col_posture', formatter: function(v) {
                    var t = window.mySimulation.t;
                    if (v === 'resist') return t('posture_short_resist');
                    if (v === 'engage') return t('posture_short_engage');
                    if (v === 'partner') return t('posture_short_partner');
                    return v;
                } },
                { key: 'results.concession', label: 'Concession', i18nKey: 'col_concession', formatter: function(v) {
                    var t = window.mySimulation.t;
                    var map = { none: 'conc_short_none', reaffirm: 'conc_short_reaffirm', audit: 'conc_short_audit', monitor: 'conc_short_monitor', pause: 'conc_short_pause', moratorium: 'conc_short_moratorium' };
                    return map[v] ? t(map[v]) : v;
                } },
                { key: 'results.mapAccuracy', label: 'Map %', i18nKey: 'col_map', formatter: function(v) { return v + '%'; } },
                { key: 'results.reputation', label: 'Reputation', i18nKey: 'col_reputation' },
                { key: 'results.campaign', label: 'Campaign', i18nKey: 'col_campaign' },
